import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics and effect sizes
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('expression', 'copy_number'):
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            effect_size = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            candidates.append((abs(t_stat), abs(effect_size), fid))

    candidates.sort(reverse=True)

    # Remove near-duplicates (correlated features with |r| >= 0.6)
    correlated_pairs = set()
    for i in range(len(candidates)):
        for j in range(i+1, len(candidates)):
            fid1, fid2 = candidates[i][2], candidates[j][2]
            if np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1] >= 0.6:
                correlated_pairs.add((fid1, fid2))

    # Keep only one feature from each correlated pair (prefer higher t-statistic)
    selected = set()
    for _, _, fid in candidates:
        # Check if this feature is part of a correlated pair
        is_correlated = False
        for pair in correlated_pairs:
            if fid in pair:
                is_correlated = True
                break

        if not is_correlated or fid not in selected:
            selected.add(fid)

    # If no mechanism found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features by t-statistic, but respect the constraint of at most 4 drivers
    top_features = [fid for _, _, fid in candidates[:4]]  # Limit to 4 drivers

    # Simple approach: select top features directly
    drivers = tuple(top_features)
    columns = tuple(top_features)

    # No interaction terms in this simple version
    products = ()

    # Simple weighted score: sum of top features
    loadings = {}
    for fid in top_features:
        col_idx = feats.column(fid)
        loadings[fid] = np.abs(np.corrcoef(feats.x[:, col_idx], feats.y)[0,1])

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

